selector_to_html = {"a[href=\"#dataflow.auth.dependencies.get_current_user\"]": "<dt class=\"sig sig-object py\" id=\"dataflow.auth.dependencies.get_current_user\">\n<em class=\"property\"><span class=\"k\"><span class=\"pre\">async</span></span><span class=\"w\"> </span></em><span class=\"sig-name descname\"><span class=\"pre\">get_current_user</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">credentials</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://fastapi.tiangolo.com/reference/security/#fastapi.security.HTTPAuthorizationCredentials\" title=\"(in FastAPI v0.0.0)\"><span class=\"pre\">fastapi.security.HTTPAuthorizationCredentials</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/library/constants.html#None\" title=\"(in Python v3.13)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">Depends(security)</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">auth</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">haive.dataflow.auth.auth.supabase.SupabaseAuth</span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">Depends(get_auth_instance)</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/library/stdtypes.html#str\" title=\"(in Python v3.13)\"><span class=\"pre\">str</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/library/constants.html#None\" title=\"(in Python v3.13)\"><span class=\"pre\">None</span></a></span></span></dt><dd><p>Verify the token and return the user ID if valid (optional\nauthentication).</p><p>This dependency function provides optional authentication for routes.\nIt extracts the JWT token from the Authorization header if present,\nvalidates it with Supabase, and returns the user ID if valid.\nIf no token is provided or the token is invalid, it returns None\ninstead of raising an exception.</p><p class=\"rubric\">Example</p></dd>", "a[href=\"../supabase/index.html#dataflow.auth.supabase.SupabaseAuth\"]": "<dt class=\"sig sig-object py\" id=\"dataflow.auth.supabase.SupabaseAuth\">\n<em class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></em><span class=\"sig-name descname\"><span class=\"pre\">SupabaseAuth</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">server_config</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">haive.dataflow.auth.config.environment.SupabaseServerConfig</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/library/constants.html#None\" title=\"(in Python v3.13)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Authentication provider using Supabase JWT.</p><p>Initialize with server-side config (for backend operations).</p></dd>", "a[href=\"#dataflow.auth.dependencies.require_auth\"]": "<dt class=\"sig sig-object py\" id=\"dataflow.auth.dependencies.require_auth\">\n<em class=\"property\"><span class=\"k\"><span class=\"pre\">async</span></span><span class=\"w\"> </span></em><span class=\"sig-name descname\"><span class=\"pre\">require_auth</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">user_id</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/library/stdtypes.html#str\" title=\"(in Python v3.13)\"><span class=\"pre\">str</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/library/constants.html#None\" title=\"(in Python v3.13)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">Depends(get_current_user)</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/library/stdtypes.html#str\" title=\"(in Python v3.13)\"><span class=\"pre\">str</span></a></span></span></dt><dd><p>Require authentication for a route (required authentication).</p><p>This dependency function provides required authentication for routes.\nIt builds on the optional authentication dependency but raises an\nHTTP exception if no valid authentication is provided, ensuring that\nthe route can only be accessed by authenticated users.</p><p class=\"rubric\">Example</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-dataflow.auth.dependencies\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.auth.dependencies<a class=\"headerlink\" href=\"#module-dataflow.auth.dependencies\" title=\"Link to this heading\">\u00b6</a></h1><p>Authentication dependencies for FastAPI routes.</p><p>This module provides FastAPI dependency functions for authentication in the\nHaive API. It includes dependencies for both optional and required authentication,\nsupporting different levels of access control for API endpoints.</p>", "a[href=\"#dataflow.auth.dependencies.security\"]": "<dt class=\"sig sig-object py\" id=\"dataflow.auth.dependencies.security\">\n<span class=\"sig-name descname\"><span class=\"pre\">security</span></span></dt><dd></dd>", "a[href=\"#dataflow.auth.dependencies.get_auth_instance\"]": "<dt class=\"sig sig-object py\" id=\"dataflow.auth.dependencies.get_auth_instance\">\n<span class=\"sig-name descname\"><span class=\"pre\">get_auth_instance</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Get the Supabase authentication instance for dependency injection.</p><p>This function creates and returns a SupabaseAuth instance configured with\nthe server settings from environment variables. It\u2019s used as a FastAPI\ndependency to provide the authentication service to route handlers.</p><p class=\"rubric\">Example</p></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`article.bd-article ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
